std::string convertMarkdownToHtml(const std::string& markdown) {
    std::string html = "";

    // Add the opening HTML tag
    html += "<html>";

    // Add the opening body tag
    html += "<body>";

    // Process the markdown text
    for (size_t i = 0; i < markdown.length(); i++) {
        char c = markdown[i];

        // Handle line breaks
        if (c == '\n') {
            html += "<br>";
        }

        // Handle bold text
        else if (c == '*') {
            html += "<strong>";
        }

        // Handle italic text
        else if (c == '_') {
            html += "<em>";
        }

        // Handle links
        else if (c == '[') {
            size_t end = markdown.find("]", i);
            if (end != std::string::npos) {
                std::string linkText = markdown.substr(i + 1, end - i - 1);
                std::string linkUrl = markdown.substr(end + 1);
                html += "<a href=\"" + linkUrl + "\">" + linkText + "</a>";
                i = end + 1;
            }
        }

        // Handle other characters
        else {
            html += c;
        }
    }

    // Add the closing body tag
    html += "</body>";

    // Add the closing HTML tag
    html += "</html>";

    return html;
}
```
